
from pathlib import Path

import pandas as pd
import plotly.express as px
import streamlit as st


def render_business_insights_page(base_dir, money, show_chart):
    report_dir = (
        Path(base_dir) / "reports" / "business_insights"
    )

    st.subheader("Business Insights & Recommendations")
    st.caption(
        "Financial performance findings generated by FinSight."
    )

    # Load generated reports
    files = {
        "overall": "overall_performance.csv",
        "country": "country_analysis.csv",
        "product": "product_analysis.csv",
        "segment": "segment_analysis.csv",
        "discount": "discount_analysis.csv",
        "insights": "business_insights.csv",
    }

    reports = {}

    for key, filename in files.items():
        path = report_dir / filename

        if not path.exists():
            st.warning(f"Report not found: {filename}")
            st.info(
                "Run: python business_insights.py "
                "from your project folder."
            )
            return

        try:
            reports[key] = pd.read_csv(path)
        except Exception as error:
            st.error(f"Could not load {filename}: {error}")
            return

    overall = reports["overall"]
    country = reports["country"]
    product = reports["product"]
    segment = reports["segment"]
    discount = reports["discount"]
    insights = reports["insights"]

    # Overall KPIs
    st.markdown("### Overall Financial Performance")

    if not overall.empty:
        row = overall.iloc[0]

        c1, c2, c3, c4 = st.columns(4)

        c1.metric(
            "Total Records",
            f"{int(row['Total Records']):,}"
        )
        c2.metric(
            "Total Sales",
            money(row["Total Sales"])
        )
        c3.metric(
            "Total Profit",
            money(row["Total Profit"])
        )
        c4.metric(
            "Profit Margin",
            f"{row['Profit Margin (%)']:.2f}%"
        )

    # Country performance
    st.markdown("### Country Performance")

    if not country.empty:
        best_country = country.loc[
            country["total_profit"].idxmax()
        ]

        st.info(
            f"Highest-profit country: {best_country['country']} "
            f"— {money(best_country['total_profit'])}"
        )

        fig = px.bar(
            country.sort_values("total_profit", ascending=True),
            x="total_profit",
            y="country",
            orientation="h",
            color="total_profit",
            title="Profit by Country",
            labels={
                "total_profit": "Total Profit",
                "country": "Country",
            },
            color_continuous_scale="Teal",
        )
        show_chart(fig, 400)

        st.dataframe(
            country,
            use_container_width=True,
            hide_index=True,
        )

    # Product performance
    st.markdown("### Product Profitability")

    if not product.empty:
        best_product = product.loc[
            product["total_profit"].idxmax()
        ]

        st.info(
            f"Most profitable product: {best_product['product']} "
            f"— {money(best_product['total_profit'])}"
        )

        fig = px.bar(
            product.sort_values("total_profit", ascending=True),
            x="total_profit",
            y="product",
            orientation="h",
            color="profit_margin_pct",
            title="Product Profitability",
            labels={
                "total_profit": "Total Profit",
                "product": "Product",
                "profit_margin_pct": "Profit Margin (%)",
            },
            color_continuous_scale="Viridis",
        )
        show_chart(fig, 400)

        st.dataframe(
            product,
            use_container_width=True,
            hide_index=True,
        )

    # Segment performance
    st.markdown("### Customer Segment Analysis")

    if not segment.empty:
        fig = px.bar(
            segment.sort_values("total_profit"),
            x="total_profit",
            y="segment",
            orientation="h",
            color="total_profit",
            title="Profit and Loss by Segment",
            labels={
                "total_profit": "Total Profit",
                "segment": "Segment",
            },
            color_continuous_scale="RdYlGn",
        )
        show_chart(fig, 400)

        losses = segment[segment["total_profit"] < 0]

        if not losses.empty:
            st.warning(
                "One or more customer segments have negative profit."
            )
            st.dataframe(
                losses,
                use_container_width=True,
                hide_index=True,
            )

        st.dataframe(
            segment,
            use_container_width=True,
            hide_index=True,
        )

    # Discount analysis
    st.markdown("### Discount Analysis")

    if not discount.empty:
        fig = px.bar(
            discount,
            x="discount_band",
            y="total_profit",
            color="total_profit",
            title="Profit by Discount Band",
            labels={
                "discount_band": "Discount Band",
                "total_profit": "Total Profit",
            },
            color_continuous_scale="Teal",
        )
        show_chart(fig, 380)

        st.dataframe(
            discount,
            use_container_width=True,
            hide_index=True,
        )

    # Insights and recommendations
    st.markdown("### Key Business Insights")

    if not insights.empty:
        for _, item in insights.iterrows():
            with st.expander(str(item["Insight"])):
                st.write(
                    f"**Finding:** {item['Finding']}"
                )
                st.write(
                    f"**Value:** {item['Value']:,.2f}"
                )
                st.write(
                    f"**Recommendation:** "
                    f"{item['Recommendation']}"
                )

        st.download_button(
            "Download Business Insights CSV",
            data=insights.to_csv(index=False).encode("utf-8"),
            file_name="finsight_business_insights.csv",
            mime="text/csv",
        )

    # Markdown report download
    markdown_path = report_dir / "business_insights_report.md"

    if markdown_path.exists():
        st.markdown("### Full Business Insights Report")

        st.download_button(
            "Download Full Report (Markdown)",
            data=markdown_path.read_bytes(),
            file_name="finsight_business_insights_report.md",
            mime="text/markdown",
        )

    st.success("Business Insights loaded successfully.")
